def biseccion(f, a, b, tol=1e-8, max_iter=100):
    if f(a) * f(b) >= 0:
        raise ValueError("Bolzano no se cumple")
    for k in range(max_iter):
        c = (a + b) / 2
        if abs(f(c)) < tol:
            return c, k
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
    return c, max_iter

if __name__ == "__main__":
    f = lambda x: x**3 - x - 2
    raiz, iters = biseccion(f, 1, 2)
    print(f"Raíz: {raiz:.10f}, iteraciones: {iters}")

# metodos/biseccion.py

def biseccion(f, a, b, tol=1e-8, max_iter=100):
    """Encuentra una raíz de f en [a, b] por bisección."""
    if f(a) * f(b) >= 0:
        raise ValueError("Bolzano no se cumple")
    for k in range(max_iter):
        c = (a + b) / 2
        if abs(f(c)) < tol:
            return c, k
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
    return c, max_iter
